INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'zh-HK', '關於我們', '<p><strong>SisterMart（姐妹商店）</strong>於 <strong>2026 年</strong>在香港成立，是一間以香港商業登記合法經營的線上選品商城，網站為 <strong>sistermart.vip</strong>。我們面向香港用戶，提供珠寶飾品及相關好物之零售、會員積分、促銷活動與售後支援。</p>\n\n<h2>商戶資料（合規披露）</h2>\n<p>為符合香港網上零售及相關合規要求，特此披露本店商業登記資料如下：</p>\n<ul>\n<li><strong>商戶名稱：</strong>SisterMart（姐妹商店）</li>\n<li><strong>商業登記號碼（BR）：</strong>41731557-000-10-26-A</li>\n<li><strong>經營地點／主要服務地區：</strong>香港特別行政區</li>\n<li><strong>官方網站：</strong>https://sistermart.vip</li>\n<li><strong>客服電郵：</strong>service@sistermart.vip</li>\n<li><strong>WhatsApp 客服：</strong>+852 5598 3063（每日 10:00–19:00，香港時間）</li>\n</ul>\n<p>你可按需要向我們查核商業登記資料；我們承諾以真實、可核實之商戶身份經營本服務。</p>\n\n<h2>我們是誰</h2>\n<p>SisterMart 希望成為姐妹們值得信賴的日常選品小店——把<strong>實惠與品質</strong>同時帶給你。我們嚴選高性價比商品，以清晰實拍與誠實標價減少「貨不對板」，並提供簡單好跟進的香港本地配送與售前售後支援。</p>\n\n<h2>我們在意什麼</h2>\n<ul>\n<li><strong>真實呈現：</strong>商品資訊與實拍盡量清晰、可對照，方便你安心下單</li>\n<li><strong>香港體驗：</strong>以香港本地配送為主，訂單狀態可在「我的訂單」查閱</li>\n<li><strong>可聯絡、可跟進：</strong>售前諮詢、物流與售後問題，均可透過「聯絡我們」找到我們</li>\n<li><strong>會員關懷：</strong>積分、簽到、優惠券等權益，旨在回饋長期支持本店的用戶</li>\n<li><strong>資料與交易安全：</strong>個人資料處理見《私隱政策》；交易與帳戶安全措施持續完善</li>\n</ul>\n\n<h2>服務範圍說明</h2>\n<ul>\n<li>目前主要服務<strong>香港地區</strong>配送（離島／偏遠地區或需另行安排）</li>\n<li>運費、出貨時效與退換貨規則，分別載於運送政策、退貨／退款政策頁面</li>\n<li>付款方式與注意事項見付款政策；使用本服務須同時遵守用戶協議</li>\n</ul>\n\n<h2>與我們聯絡</h2>\n<p>購物、訂單、售後或商戶資料查詢，歡迎透過頁腳「聯絡我們」、電郵 <strong>service@sistermart.vip</strong> 或 WhatsApp <strong>+852 5598 3063</strong> 與我們溝通。謝謝你選擇 SisterMart——期待陪你找到喜歡的好物。</p>\n'
FROM articles a WHERE a.code='about'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'en', 'About Us', '<p><strong>SisterMart</strong> was founded in <strong>2026</strong> in Hong Kong as an online boutique lawfully operating under a Hong Kong Business Registration. Our website is <strong>sistermart.vip</strong>. We serve customers in Hong Kong with jewellery and related goods, membership points, promotions and after-sales support.</p>\n\n<h2>Merchant details (compliance disclosure)</h2>\n<p>To meet Hong Kong online retail and related compliance expectations, we disclose our business registration details as follows:</p>\n<ul>\n<li><strong>Merchant name:</strong> SisterMart</li>\n<li><strong>Business Registration No. (BR):</strong> 41731557-000-10-26-A</li>\n<li><strong>Place of business / primary service area:</strong> Hong Kong Special Administrative Region</li>\n<li><strong>Official website:</strong> https://sistermart.vip</li>\n<li><strong>Customer service email:</strong> service@sistermart.vip</li>\n<li><strong>WhatsApp support:</strong> +852 5598 3063 (daily 10:00–19:00, Hong Kong time)</li>\n</ul>\n<p>You may ask us to verify our BR details. We operate this Service under a genuine, verifiable merchant identity.</p>\n\n<h2>Who we are</h2>\n<p>SisterMart aims to be a trusted everyday boutique for our community—bringing <strong>affordable quality</strong> together. We curate great-value picks, use clear product photos and honest pricing to reduce mismatches, and offer straightforward Hong Kong local delivery with friendly support before and after your order.</p>\n\n<h2>What we care about</h2>\n<ul>\n<li><strong>Honest presentation:</strong> clear product information and real photos so you can order with confidence</li>\n<li><strong>Hong Kong experience:</strong> mainly local HK shipping; track status in My Orders</li>\n<li><strong>Reachable support:</strong> pre-sale questions, logistics and after-sales via Contact Us</li>\n<li><strong>Member care:</strong> points, check-ins and coupons to thank returning customers</li>\n<li><strong>Data &amp; transaction security:</strong> see our Privacy Policy; we keep improving account and payment safeguards</li>\n</ul>\n\n<h2>Service scope</h2>\n<ul>\n<li>We currently ship mainly within <strong>Hong Kong</strong> (outlying/remote areas may need special arrangement)</li>\n<li>Shipping fees, lead times and return/refund rules are set out in the Shipping, Return and Refund policy pages</li>\n<li>Payment methods are described in the Payment Policy; using the Service is also subject to our User Agreement</li>\n</ul>\n\n<h2>Contact us</h2>\n<p>For shopping, orders, after-sales or merchant identity questions, reach us via Contact Us in the footer, email <strong>service@sistermart.vip</strong>, or WhatsApp <strong>+852 5598 3063</strong>. Thank you for choosing SisterMart—we look forward to helping you find pieces you love.</p>\n'
FROM articles a WHERE a.code='about'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

