INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'zh-HK', '聯絡我們', '<p>購物、訂單、售後、帳戶或商戶資料查詢，歡迎透過以下方式聯絡 <strong>SisterMart（姐妹商店）</strong>。我們會盡快回覆；請盡量提供訂單編號與問題說明，以便更快處理。</p>\n\n<h2>1. 客服電郵</h2>\n<p>電郵：<a href="mailto:service@sistermart.vip">service@sistermart.vip</a></p>\n<p>適合較長說明、附件截圖，或非即時可等候回覆的查詢。一般於工作時間內回覆；複雜個案或需核對訂單／物流時，回覆可能需要稍長時間。</p>\n<ul>\n<li>建議主旨註明：訂單編號／問題類型（例如「物流查詢」「退換貨」「帳戶」）</li>\n<li>正文請附：會員電郵或手機、訂單編號、問題描述與相關圖片（如適用）</li>\n</ul>\n\n<h2>2. 線上聊天（WhatsApp）</h2>\n<p><a href="https://wa.me/85255983063" target="_blank" rel="noopener noreferrer" class="sm-contact-btn sm-contact-wa">WhatsApp 客服</a></p>\n<p>號碼：<strong>+852 5598 3063</strong></p>\n<p>工作時間：每日 <strong>10:00–19:00</strong>（香港時間）。非工作時段留言，我們會在下一工作時段回覆。適合快速確認訂單狀態、地址修改與即時售前諮詢。</p>\n\n<h2>3. 社交媒體</h2>\n<p>你也可以在社交平台找到我們。繁忙時段該渠道<strong>可能需要排隊</strong>，感謝耐心等候。訂單與私隱相關事宜，建議優先使用電郵或 WhatsApp，以便核實身份與訂單資料。</p>\n<p><a href="https://www.facebook.com/" target="_blank" rel="noopener noreferrer" class="sm-contact-btn sm-contact-fb">Facebook</a></p>\n\n<h2>4. 我們可以協助什麼</h2>\n<ul>\n<li>商品與庫存／規格諮詢</li>\n<li>下單、付款狀態與發票／收據相關查詢</li>\n<li>配送進度、改址與簽收問題</li>\n<li>售後、退換貨與評價相關協助</li>\n<li>帳戶、驗證碼與會員權益（積分／優惠券）問題</li>\n<li>私隱或商戶資料（商業登記）查詢</li>\n</ul>\n\n<h2>5. 回覆時效說明</h2>\n<ul>\n<li><strong>工作時間內：</strong>一般於當日回覆 WhatsApp／電郵</li>\n<li><strong>非工作時間／公眾假期：</strong>下一工作時段起陸續處理</li>\n<li><strong>需第三方協助者</strong>（如物流、支付機構）：以對方回覆進度為準，我們會同步告知你</li>\n</ul>\n\n<p>官方網站：<strong>https://sistermart.vip</strong>。更多店舖資訊見「關於我們」；個人資料處理見「私隱政策」。</p>\n'
FROM articles a WHERE a.code='contact'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'en', 'Contact Us', '<p>For shopping, orders, after-sales, account or merchant identity questions, contact <strong>SisterMart</strong> below. We will reply as soon as we can—please include your order number and a short description so we can help faster.</p>\n\n<h2>1. Customer service email</h2>\n<p>Email: <a href="mailto:service@sistermart.vip">service@sistermart.vip</a></p>\n<p>Best for longer explanations, screenshots/attachments, or queries that do not need an instant reply. We usually respond during business hours; complex cases that need order or logistics checks may take longer.</p>\n<ul>\n<li>Suggested subject: order number / topic (e.g. “shipping”, “return”, “account”)</li>\n<li>Please include: member email or phone, order number, description, and relevant images if applicable</li>\n</ul>\n\n<h2>2. Live chat (WhatsApp)</h2>\n<p><a href="https://wa.me/85255983063" target="_blank" rel="noopener noreferrer" class="sm-contact-btn sm-contact-wa">WhatsApp support</a></p>\n<p>Number: <strong>+852 5598 3063</strong></p>\n<p>Hours: daily <strong>10:00–19:00</strong> (Hong Kong time). Messages outside hours will be answered in the next working window. Ideal for quick order status checks, address changes and pre-sale questions.</p>\n\n<h2>3. Social media</h2>\n<p>You can also find us on social media. During busy periods this channel <strong>may require queuing</strong>—thanks for your patience. For order or privacy matters, please prefer email or WhatsApp so we can verify your identity and order details.</p>\n<p><a href="https://www.facebook.com/" target="_blank" rel="noopener noreferrer" class="sm-contact-btn sm-contact-fb">Facebook</a></p>\n\n<h2>4. How we can help</h2>\n<ul>\n<li>Product, stock and specification questions</li>\n<li>Checkout, payment status and receipt-related queries</li>\n<li>Delivery progress, address changes and receipt issues</li>\n<li>After-sales, returns/exchanges and review support</li>\n<li>Account, OTP and membership benefits (points/coupons)</li>\n<li>Privacy or merchant identity (Business Registration) enquiries</li>\n</ul>\n\n<h2>5. Response times</h2>\n<ul>\n<li><strong>During business hours:</strong> we usually reply to WhatsApp/email the same day</li>\n<li><strong>Outside hours / public holidays:</strong> we process messages from the next working window</li>\n<li><strong>Cases needing third parties</strong> (logistics, payment providers): timing depends on their response; we will keep you updated</li>\n</ul>\n\n<p>Official website: <strong>https://sistermart.vip</strong>. See About Us for more store details and our Privacy Policy for personal data handling.</p>\n'
FROM articles a WHERE a.code='contact'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

